/* @autogenerated */
package net.civeira.phylax.feature.observe.slo;

import java.util.List;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.feature.observe.metric.Histogram;
import net.civeira.phylax.feature.observe.metric.MetricPoint;

class SloMathUnitTest {

  private static MetricPoint point(final long ts, final long count, final long errors,
      final double... millis) {
    Histogram histogram = new Histogram();
    for (double value : millis) {
      histogram.add(value);
    }
    return new MetricPoint(ts, 60_000, "api", "/orders", "GET", count, errors, 0,
        histogram.counts());
  }

  @Test
  @DisplayName("Availability: good are the requests without error; burn 1 spends the budget in the window")
  void availability() {
    List<MetricPoint> points = List.of(point(0, 1000, 5), point(60_000, 1000, 5));
    SloMath.Counts counts = SloMath.counts(points, null, null, 0, 120_000);
    Assertions.assertEquals(1990, counts.good());
    Assertions.assertEquals(2000, counts.total());
    Assertions.assertEquals(1.0, SloMath.burn(counts, 0.995), 0.0001);
    Assertions.assertEquals(0.0, SloMath.budgetRemaining(counts, 0.995), 0.0001);
    Assertions.assertEquals(0, SloMath.counts(points, "/other", null, 0, 120_000).total());
  }

  @Test
  @DisplayName("Latency: good are the requests in the buckets up to the limit")
  void latency() {
    List<MetricPoint> points = List.of(point(0, 4, 0, 30, 90, 400, 3000));
    Assertions.assertEquals(2, SloMath.counts(points, null, 100, 0, 60_000).good());
    Assertions.assertEquals(3, SloMath.counts(points, null, 500, 0, 60_000).good());
    Assertions.assertEquals(-1, SloMath.bucketIndex(1));
  }

  @Test
  @DisplayName("A fast burn above 14.4 in 1 h; nothing to burn without traffic")
  void fastBurn() {
    SloMath.Counts counts = new SloMath.Counts(900, 1000);
    Assertions.assertTrue(SloMath.burn(counts, 0.995) > SloMath.FAST_BURN);
    Assertions.assertEquals(0, SloMath.burn(new SloMath.Counts(0, 0), 0.995));
  }
}
